    def fill_line(coords):
        # coords is an ordered list of (r, c) positions on one line
        marks = [i for i, (r, c) in enumerate(coords)
                 if grid[r][c] != background]
        runs = []
        if marks:
            start = prev = marks[0]
            for i in marks[1:]:
                if i != prev + 1:
                    runs.append(prev - start + 1)
                    start = i
                prev = i
            runs.append(prev - start + 1)

        # These lines contain a prominent bar, or multiple aligned bars.
        active = any(length >= 3 for length in runs)
        if len([length for length in runs if length >= 2]) >= 2 and all(
            length >= 2 for length in runs
        ):
            active = True

        if active and marks:
            for i in range(marks[0], marks[-1] + 1):
                r, c = coords[i]
                if grid[r][c] == background:
                    out[r][c] = 2

    for r in range(h):
        fill_line([(r, c) for c in range(w)])
    for c in range(w):
        fill_line([(r, c) for r in range(h)])

